<?php
namespace App\Http\Controllers\Government;
use App\Http\Controllers\Controller; use App\Models\{Agency,AgencyLicense,Inspection,SettaBook,SettaSerial,Violation}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class RegistryController extends Controller {
 public function licenses(){return view('government.licenses',['licenses'=>AgencyLicense::with('agency')->latest()->paginate(30),'agencies'=>Agency::orderBy('name')->get()]);}
 public function storeLicense(Request $r){$d=$r->validate(['agency_id'=>'required|integer','license_number'=>'required|unique:agency_licenses,license_number','holder_name'=>'required','issue_date'=>'nullable|date','expiry_date'=>'nullable|date','status'=>'required']);AgencyLicense::create($d);Agency::findOrFail($d['agency_id'])->update(['license_number'=>$d['license_number'],'license_status'=>$d['status'],'license_expires_at'=>$d['expiry_date']??null,'is_verified'=>$d['status']==='active']);return back()->with('success','License recorded.');}
 public function setta(){return view('government.setta',['books'=>SettaBook::withoutGlobalScopes()->with('agency')->latest()->paginate(20),'agencies'=>Agency::orderBy('name')->get()]);}
 public function storeSettaBook(Request $r){$d=$r->validate(['agency_id'=>'required|integer','book_no'=>'required','type'=>'required','range_start'=>'required|integer','range_end'=>'required|integer|gte:range_start']);return DB::transaction(function()use($d){$book=SettaBook::withoutGlobalScopes()->create($d+['issued_at'=>now(),'issued_by'=>auth()->id(),'status'=>'issued']);for($i=$d['range_start'];$i<=$d['range_end'];$i++)SettaSerial::withoutGlobalScopes()->create(['agency_id'=>$d['agency_id'],'setta_book_id'=>$book->id,'serial_no'=>(string)$i,'type'=>$d['type'],'status'=>'available','assigned_at'=>now()]);return back()->with('success','Setta book and serial inventory created.');});}
 public function inspections(){return view('government.inspections',['items'=>Inspection::withoutGlobalScopes()->with('agency')->latest()->paginate(30),'agencies'=>Agency::orderBy('name')->get()]);}
 public function storeInspection(Request $r){$d=$r->validate(['agency_id'=>'required|integer','inspected_at'=>'required|date','latitude'=>'nullable|numeric','longitude'=>'nullable|numeric','status'=>'required','summary'=>'nullable']);Inspection::withoutGlobalScopes()->create($d+['inspector_user_id'=>auth()->id()]);return back()->with('success','Inspection recorded.');}
 public function violations(){return view('government.violations',['items'=>Violation::withoutGlobalScopes()->with('agency')->latest()->paginate(30),'agencies'=>Agency::orderBy('name')->get()]);}
 public function storeViolation(Request $r){$d=$r->validate(['agency_id'=>'required|integer','inspection_id'=>'nullable|integer','type'=>'required','severity'=>'required','description'=>'required','action_taken'=>'nullable']);Violation::withoutGlobalScopes()->create($d+['status'=>'open','detected_at'=>now()]);return back()->with('success','Violation recorded.');}
}
